    word_indices = {}
    for i, word in enumerate(words):
        start = message.find(word)
        end = start + len(word) - 1
        word_indices[(start, end)] = word

    spoiler_set = set()
    for start, end in spoiler_ranges:
        for (w_start, w_end), word in word_indices.items():
            if w_start >= start and w_end <= end:
                spoiler_set.add(word)

    important_words = set()
    non_spoiler_indices = set(range(len(message)))
    for start, end in spoiler_ranges:
        for (w_start, w_end), word in word_indices.items():
            if w_start >= start and w_end <= end:
                if word not in important_words and word not in spoiler_set:
                    if all(i not in non_spoiler_indices for i in range(len(message)) if i < w_start or i > w_end):
